#!/bin/sh
# Generated by scripts/installer/unix.mjs. The release copy is self-contained:
# it embeds the exact version, artifact name, size and SHA-256.
set -eu
umask 077

ZYLARA_VERSION=@VERSION@
ZYLARA_PLATFORM=@PLATFORM@
ZYLARA_ARCH=@ARCH@
ZYLARA_PAYLOAD_NAME=@PAYLOAD_NAME@
ZYLARA_PAYLOAD_SIZE=@PAYLOAD_SIZE@
ZYLARA_PAYLOAD_SHA256=@PAYLOAD_SHA256@
ZYLARA_PAYLOAD_URL=@PAYLOAD_URL@
ZYLARA_HTTPS=@HTTPS@
ZYLARA_DATA_DIR_NAME=@DATA_DIR_NAME@

LANG_CODE="${ZYLARA_LANG:-${LC_ALL:-${LANG:-en}}}"
case "$LANG_CODE" in
  pt*) LANG_CODE=pt ;;
  es*) LANG_CODE=es ;;
  *) LANG_CODE=en ;;
esac

say() {
  case "${LANG_CODE}:$1" in
@MESSAGE_CASES@
    *) printf '%s\n' "$1" ;;
  esac
}

die() {
  say "$1"
  if [ -n "${2:-}" ]; then
    printf '%s\n' "$2"
  fi
  exit 1
}

need() {
  command -v "$1" >/dev/null 2>&1
}

WORK=''
MOUNT=''
STAGE_FILE=''
STAGE_DIR=''
DESKTOP_TMP=''
MARKER_TMP=''

cleanup() {
  if [ -n "$MOUNT" ]; then
    hdiutil detach "$MOUNT" >/dev/null 2>&1 || true
  fi
  if [ -n "$STAGE_FILE" ]; then
    rm -f "$STAGE_FILE"
  fi
  if [ -n "$STAGE_DIR" ]; then
    rm -rf "$STAGE_DIR"
  fi
  if [ -n "$DESKTOP_TMP" ]; then
    rm -f "$DESKTOP_TMP"
  fi
  if [ -n "$MARKER_TMP" ]; then
    rm -f "$MARKER_TMP"
  fi
  if [ -n "$WORK" ]; then
    rm -rf "$WORK"
  fi
}
trap cleanup EXIT

OS_NAME=$(uname -s 2>/dev/null || true)
MACHINE=$(uname -m 2>/dev/null || true)
case "$OS_NAME" in
  Linux) [ "$ZYLARA_PLATFORM" = linux ] || die platform ;;
  Darwin) [ "$ZYLARA_PLATFORM" = macos ] || die platform ;;
  *) die platform ;;
esac
case "$MACHINE" in
  x86_64|amd64) MACHINE_ARCH=x64 ;;
  arm64|aarch64) MACHINE_ARCH=arm64 ;;
  *) die arch ;;
esac
if [ "$MACHINE_ARCH" != "$ZYLARA_ARCH" ]; then
  die arch
fi

if [ -z "${HOME:-}" ]; then
  die home
fi
case "$HOME" in
  /*) ;;
  *) die home ;;
esac

if [ "$ZYLARA_PLATFORM" = macos ]; then
  DATA_ROOT="$HOME/Library/Application Support"
else
  if [ -n "${XDG_DATA_HOME:-}" ]; then
    case "$XDG_DATA_HOME" in
      /*) DATA_ROOT="$XDG_DATA_HOME" ;;
      *) DATA_ROOT="$HOME/.local/share" ;;
    esac
  else
    DATA_ROOT="$HOME/.local/share"
  fi
fi
MARKER_DIR="$DATA_ROOT/$ZYLARA_DATA_DIR_NAME"
MARKER_PATH="$MARKER_DIR/managed-install.json"

MISSING=''
if ! need curl && ! need wget; then
  MISSING="$MISSING curl|wget"
fi
if ! need sha256sum && ! need shasum && ! need openssl; then
  MISSING="$MISSING sha256sum|shasum|openssl"
fi
if [ "$ZYLARA_PLATFORM" = macos ]; then
  for tool in hdiutil ditto plutil open; do
    if ! need "$tool"; then
      MISSING="$MISSING $tool"
    fi
  done
fi
if [ -n "$MISSING" ]; then
  say tools
  printf '%s\n' "$MISSING"
  exit 1
fi

if [ "$ZYLARA_PLATFORM" = linux ]; then
  TARGET_DIR="$HOME/.local/opt/zylara"
  TARGET="$TARGET_DIR/Zylara.AppImage"
else
  TARGET_DIR="$HOME/Applications"
  TARGET="$TARGET_DIR/Zylara.app"
fi

if [ -L "$TARGET" ]; then
  die target
fi
if [ "$ZYLARA_PLATFORM" = linux ]; then
  if [ -e "$TARGET" ] && [ ! -f "$TARGET" ]; then
    die target
  fi
else
  if [ -e "$TARGET" ] && [ ! -d "$TARGET" ]; then
    die target
  fi
fi

mkdir -p "$TARGET_DIR" || die install
mkdir -p "$MARKER_DIR" || die marker

PAYLOAD_KB=$(( (ZYLARA_PAYLOAD_SIZE + 1023) / 1024 ))
NEED_KB=$(( PAYLOAD_KB + 10240 ))
AVAIL_KB=$(df -Pk "$TARGET_DIR" 2>/dev/null | awk 'NR==2 {print $4}' || true)
case "$AVAIL_KB" in
  ''|*[!0-9]*) ;;
  *)
    if [ "$AVAIL_KB" -lt "$NEED_KB" ]; then
      die space
    fi
    ;;
esac

WORK=$(mktemp -d "${TMPDIR:-/tmp}/zylara-install.XXXXXX") || die download
PAYLOAD="$WORK/$ZYLARA_PAYLOAD_NAME"
if need curl; then
  if [ "$ZYLARA_HTTPS" = 1 ]; then
    curl -fL --proto '=https' --tlsv1.2 --retry 2 -o "$PAYLOAD" "$ZYLARA_PAYLOAD_URL" || die download
  else
    curl -fL --retry 2 -o "$PAYLOAD" "$ZYLARA_PAYLOAD_URL" || die download
  fi
else
  wget -q --tries=2 -O "$PAYLOAD" "$ZYLARA_PAYLOAD_URL" || die download
fi

ACTUAL_SIZE=$(wc -c < "$PAYLOAD" | tr -d '[:space:]')
if [ "$ACTUAL_SIZE" != "$ZYLARA_PAYLOAD_SIZE" ]; then
  die size
fi

sha256_of() {
  if need sha256sum; then
    sha256sum "$1" | awk '{print $1}'
  elif need shasum; then
    shasum -a 256 "$1" | awk '{print $1}'
  elif need openssl; then
    openssl dgst -sha256 "$1" | awk '{print $NF}'
  else
    return 1
  fi
}
ACTUAL_SHA=$(sha256_of "$PAYLOAD" || true)
ACTUAL_SHA=$(printf '%s' "$ACTUAL_SHA" | tr 'A-F' 'a-f')
if [ "$ACTUAL_SHA" != "$ZYLARA_PAYLOAD_SHA256" ]; then
  die hash
fi

if [ "$ZYLARA_PLATFORM" = linux ]; then
  STAGE_FILE="$TARGET_DIR/.Zylara.AppImage.new.$$"
  cp "$PAYLOAD" "$STAGE_FILE" || die install
  chmod 755 "$STAGE_FILE" || die install
  if ! mv -f "$STAGE_FILE" "$TARGET"; then
    die install
  fi
  STAGE_FILE=''
else
  MOUNT="$WORK/mnt"
  mkdir -p "$MOUNT" || die install
  hdiutil attach -nobrowse -readonly -mountpoint "$MOUNT" "$PAYLOAD" >/dev/null 2>&1 || die dmg
  set -- "$MOUNT"/*.app
  if [ "$#" -ne 1 ] || [ ! -d "$1" ]; then
    die dmg
  fi
  SOURCE_APP="$1"
  BUNDLE_ID=$(plutil -extract CFBundleIdentifier raw -o - "$SOURCE_APP/Contents/Info.plist" 2>/dev/null || true)
  if [ "$BUNDLE_ID" != "app.zylara.chat" ]; then
    die dmg
  fi
  BUNDLE_EXECUTABLE=$(plutil -extract CFBundleExecutable raw -o - "$SOURCE_APP/Contents/Info.plist" 2>/dev/null || true)
  if [ -z "$BUNDLE_EXECUTABLE" ] || [ ! -x "$SOURCE_APP/Contents/MacOS/$BUNDLE_EXECUTABLE" ]; then
    die dmg
  fi
  STAGE_DIR="$TARGET_DIR/.Zylara.app.stage.$$"
  mkdir -p "$STAGE_DIR" || die install
  ditto "$SOURCE_APP" "$STAGE_DIR/Zylara.app" || die install
  if hdiutil detach "$MOUNT" >/dev/null 2>&1; then
    MOUNT=''
  fi
  if need codesign; then
    if codesign -dv "$STAGE_DIR/Zylara.app" >/dev/null 2>&1; then
      if ! codesign --verify --deep --strict "$STAGE_DIR/Zylara.app" >/dev/null 2>&1; then
        die dmg
      fi
    fi
  fi
  BACKUP="$TARGET_DIR/.Zylara.app.bak.$$"
  if [ -e "$TARGET" ]; then
    if ! mv "$TARGET" "$BACKUP"; then
      die backup
    fi
  fi
  if ! mv "$STAGE_DIR/Zylara.app" "$TARGET"; then
    if [ -e "$BACKUP" ]; then
      mv "$BACKUP" "$TARGET" >/dev/null 2>&1 || true
    fi
    die promote
  fi
  rm -rf "$STAGE_DIR" || true
  STAGE_DIR=''
  if [ -e "$BACKUP" ]; then
    rm -rf "$BACKUP" || true
  fi
fi

if [ "$ZYLARA_PLATFORM" = linux ]; then
  DESKTOP_DIR="$DATA_ROOT/applications"
  DESKTOP="$DESKTOP_DIR/zylara-managed.desktop"
  mkdir -p "$DESKTOP_DIR" || die desktop
  desktop_escape() {
    printf '%s' "$1" | sed 's/\\/\\\\/g; s/"/\\"/g; s/`/\\`/g; s/\$/\\$/g'
  }
  TARGET_ESCAPED=$(desktop_escape "$TARGET" || true)
  DESKTOP_TMP="$DESKTOP.tmp.$$"
  {
    printf '%s\n' '[Desktop Entry]'
    printf '%s\n' 'Type=Application'
    printf '%s\n' 'Name=Zylara'
    printf '%s\n' 'Comment=AI chat desktop app'
    printf 'Exec="%s" %%U\n' "$TARGET_ESCAPED"
    printf 'TryExec=%s\n' "$TARGET"
    printf '%s\n' 'Terminal=false'
    printf '%s\n' 'Categories=Utility;'
    printf '%s\n' 'StartupNotify=true'
    printf '%s\n' 'X-Zylara-Managed=true'
  } > "$DESKTOP_TMP" || die desktop
  chmod 644 "$DESKTOP_TMP" || die desktop
  if ! mv -f "$DESKTOP_TMP" "$DESKTOP"; then
    die desktop
  fi
  DESKTOP_TMP=''
fi

json_escape() {
  printf '%s' "$1" | sed 's/\\/\\\\/g; s/"/\\"/g'
}
TARGET_JSON=$(json_escape "$TARGET" || true)
MARKER_TMP="$MARKER_PATH.tmp.$$"
{
  printf '{\n'
  printf '  "schemaVersion": 1,\n'
  printf '  "method": "managed-script",\n'
  printf '  "platform": "%s",\n' "$ZYLARA_PLATFORM"
  printf '  "arch": "%s",\n' "$ZYLARA_ARCH"
  printf '  "installPath": "%s",\n' "$TARGET_JSON"
  printf '  "version": "%s"\n' "$ZYLARA_VERSION"
  printf '}\n'
} > "$MARKER_TMP" || die marker
chmod 600 "$MARKER_TMP" || die marker
if ! mv -f "$MARKER_TMP" "$MARKER_PATH"; then
  die marker
fi
MARKER_TMP=''

if [ "${ZYLARA_NO_LAUNCH:-0}" != 1 ]; then
  if [ "$ZYLARA_PLATFORM" = macos ]; then
    open "$TARGET" >/dev/null 2>&1 || true
  else
    nohup "$TARGET" >/dev/null 2>&1 &
  fi
fi

say done
printf '%s\n' "$TARGET"
